// Embedded copy of Images/scythe.glb so the model still loads when index.html is opened
// straight from disk (file://), where browsers block fetching the .glb file.
// Regenerate this file if scythe.glb is re-exported.
window.EMBEDDED_MODELS = window.EMBEDDED_MODELS || {};
window.EMBEDDED_MODELS["Images/scythe.glb"] = "data:model/gltf-binary;base64,";
